using System.Text;
using Microsoft.Extensions.Logging;
using ShortsGenerator.Domain;

namespace ShortsGenerator.Application;

/// <param name="Resumed">True when the job went on to narration (everything present, or skipped).</param>
/// <param name="Imported">Asset ids added to the catalog by this call.</param>
/// <param name="Missing">Pictures still not supplied.</param>
public sealed record ArtContinueResult(bool Resumed, IReadOnlyList<string> Imported, IReadOnlyList<ArtRequest> Missing);

// The "art gate" between the scene plan and the narration. While the art is generated by
// hand (ChatGPT, see docs/ART_PROMPTS_READY.md), the pipeline can't draw what it lacks, so it
// stops and asks: one ready-to-paste prompt per missing picture, saved as art-requests.md in
// the job's folder and shown in the dashboard. The owner drops the images in, presses
// Continue, and the job goes on from the same plan - nothing is regenerated.
public sealed class ArtRequestService
{
    public const string RequestsFileName = "art-requests.md";

    private readonly IVideoJobRepository _repository;
    private readonly IVideoPlanStore _planStore;
    private readonly IAssetRepository _assets;
    private readonly IArtSubjectCatalog _subjects;
    private readonly IArtImporter _importer;
    private readonly IJobArtifactWriter _artifacts;
    private readonly TimeProvider _timeProvider;
    private readonly ILogger<ArtRequestService> _logger;

    public ArtRequestService(
        IVideoJobRepository repository,
        IVideoPlanStore planStore,
        IAssetRepository assets,
        IArtSubjectCatalog subjects,
        IArtImporter importer,
        IJobArtifactWriter artifacts,
        TimeProvider timeProvider,
        ILogger<ArtRequestService> logger)
    {
        _repository = repository;
        _planStore = planStore;
        _assets = assets;
        _subjects = subjects;
        _importer = importer;
        _artifacts = artifacts;
        _timeProvider = timeProvider;
        _logger = logger;
    }

    /// <summary>
    /// Pipeline gate, run once per plan before narration. Points every scene at the art for
    /// the subject it talks about; if some of that art doesn't exist, writes the prompts and
    /// puts the job in WaitingForArt. Returns true when the job now waits.
    /// </summary>
    public async Task<bool> HoldForArtAsync(Guid jobId, CancellationToken cancellationToken)
    {
        var plan = await _planStore.LoadAsync(jobId, cancellationToken);
        if (plan is null || plan.ArtChecked)
        {
            return false;
        }

        var check = await CheckAsync(plan, cancellationToken);
        if (check.Requests.Count == 0)
        {
            await _planStore.SaveAsync(jobId, await FinishAsync(jobId, plan with { Scenes = check.Scenes }, cancellationToken), cancellationToken);
            return false;
        }

        await _planStore.SaveAsync(jobId, plan with { Scenes = check.Scenes }, cancellationToken);
        var job = await _repository.GetByIdAsync(jobId, cancellationToken)
                  ?? throw new KeyNotFoundException($"Video job '{jobId}' was not found.");
        await WriteRequestsAsync(job, check.Requests, cancellationToken);
        job.MarkWaitingForArt(_timeProvider.GetUtcNow());
        await _repository.UpdateAsync(job, cancellationToken);
        _logger.LogInformation(
            "Job {JobId} waits for {Count} picture(s): {Files}",
            jobId, check.Requests.Count, string.Join(", ", check.Requests.Select(r => r.Subject.IncomingFileName)));
        return true;
    }

    /// <summary>The pictures the job's plan still needs (empty when none, or no plan yet).</summary>
    public async Task<IReadOnlyList<ArtRequest>> GetRequestsAsync(Guid jobId, CancellationToken cancellationToken)
    {
        var plan = await _planStore.LoadAsync(jobId, cancellationToken);
        return plan is null ? [] : (await CheckAsync(plan, cancellationToken)).Requests;
    }

    public bool HasSource(ArtRequest request) => _importer.HasSource(request.Subject);

    /// <summary>Stores an uploaded picture - only under a file name the job actually asked for.</summary>
    /// <exception cref="KeyNotFoundException">The job doesn't ask for this file.</exception>
    public async Task SaveUploadAsync(Guid jobId, string fileName, Stream content, CancellationToken cancellationToken)
    {
        var request = (await GetRequestsAsync(jobId, cancellationToken))
            .FirstOrDefault(r => string.Equals(r.Subject.IncomingFileName, fileName, StringComparison.OrdinalIgnoreCase))
            ?? throw new KeyNotFoundException($"Video job '{jobId}' doesn't need a picture named '{fileName}'.");
        await _importer.SaveSourceAsync(request.Subject, content, cancellationToken);
    }

    /// <summary>
    /// Imports every supplied picture, re-checks the plan, and resumes the job when nothing is
    /// missing - or regardless, when <paramref name="skipMissing"/> (the scenes without art keep
    /// the plan's own pick or the mascot).
    /// </summary>
    /// <exception cref="InvalidOperationException">The job isn't waiting for art.</exception>
    /// <exception cref="ArtImportException">A supplied picture couldn't be processed.</exception>
    public async Task<ArtContinueResult> ContinueAsync(Guid jobId, bool skipMissing, CancellationToken cancellationToken)
    {
        var job = await _repository.GetByIdAsync(jobId, cancellationToken)
                  ?? throw new KeyNotFoundException($"Video job '{jobId}' was not found.");
        if (job.Status != VideoJobStatus.WaitingForArt)
        {
            throw new InvalidOperationException($"Video job '{jobId}' is '{job.Status}', not waiting for art.");
        }

        var plan = await _planStore.LoadAsync(jobId, cancellationToken)
                   ?? throw new InvalidOperationException($"Video job '{jobId}' has no plan.");

        var imported = new List<string>();
        foreach (var request in (await CheckAsync(plan, cancellationToken)).Requests.Where(r => _importer.HasSource(r.Subject)))
        {
            imported.AddRange(await _importer.ImportAsync(request.Subject, cancellationToken));
            _logger.LogInformation("Job {JobId}: imported {File}", jobId, request.Subject.IncomingFileName);
        }

        var check = await CheckAsync(plan, cancellationToken);
        if (check.Requests.Count > 0 && !skipMissing)
        {
            await _planStore.SaveAsync(jobId, plan with { Scenes = check.Scenes }, cancellationToken);
            await WriteRequestsAsync(job, check.Requests, cancellationToken);
            return new ArtContinueResult(false, imported, check.Requests);
        }

        await _planStore.SaveAsync(jobId, await FinishAsync(jobId, plan with { Scenes = check.Scenes }, cancellationToken), cancellationToken);
        job.ResumeAfterArt(_timeProvider.GetUtcNow());
        await _repository.UpdateAsync(job, cancellationToken);
        if (check.Requests.Count > 0)
        {
            _logger.LogWarning(
                "Job {JobId} continues without {Files}",
                jobId, string.Join(", ", check.Requests.Select(r => r.Subject.IncomingFileName)));
        }

        return new ArtContinueResult(true, imported, check.Requests);
    }

    // The last word on what the video shows before the voice-over: every needed picture is
    // there (or skipped), so the expressions, hook motion and look set are chosen now, against
    // the videos already made (VisualDirector).
    private async Task<VideoPlan> FinishAsync(Guid jobId, VideoPlan plan, CancellationToken cancellationToken)
    {
        var earlier = new List<VideoPlan>();
        foreach (var job in (await _repository.ListRecentAsync(VisualDirector.RecentVideos * 5, cancellationToken))
                     .Where(j => j.Status == VideoJobStatus.Completed && j.Id != jobId)
                     .Take(VisualDirector.RecentVideos))
        {
            if (await _planStore.LoadAsync(job.Id, cancellationToken) is { } earlierPlan)
            {
                earlier.Add(earlierPlan);
            }
        }

        var catalog = await _assets.GetAllAsync(cancellationToken);
        var directed = VisualDirector.Direct(plan, earlier, catalog.Select(a => a.Id).ToList(), jobId.GetHashCode() & int.MaxValue);
        return directed with { ArtChecked = true };
    }

    private async Task<ArtCheck> CheckAsync(VideoPlan plan, CancellationToken cancellationToken)
    {
        var catalog = await _assets.GetAllAsync(cancellationToken);
        var subjects = await _subjects.GetAllAsync(cancellationToken);
        return ArtGapDetector.Check(plan.Scenes, catalog.Select(a => a.Id).ToList(), subjects);
    }

    private Task WriteRequestsAsync(VideoJob job, IReadOnlyList<ArtRequest> requests, CancellationToken cancellationToken) =>
        _artifacts.WriteTextAsync(job.Id, RequestsFileName, RenderRequests(job.Topic, requests), cancellationToken);

    public static string RenderRequests(string topic, IReadOnlyList<ArtRequest> requests)
    {
        var sb = new StringBuilder();
        sb.AppendLine($"# Pictures needed for \"{topic}\"");
        sb.AppendLine();
        sb.AppendLine($"{requests.Count} picture(s) are missing from the catalog. For each one: paste the prompt into the image");
        sb.AppendLine("tool, attach `assets/mascot/mascot-idle.png` as the reference image where it says so, and save the");
        sb.AppendLine("result under the file name shown - upload it in the dashboard, or put it into `assets/incoming/`.");
        sb.AppendLine("Then press Continue in the dashboard (or `continue.cmd <job-id>`).");
        foreach (var (request, index) in requests.Select((r, i) => (r, i + 1)))
        {
            sb.AppendLine();
            sb.AppendLine($"## {index}. `{request.Subject.IncomingFileName}`");
            sb.AppendLine();
            sb.AppendLine($"For scene(s) {string.Join(", ", request.SceneIds)}. " +
                          (ArtPromptBuilder.NeedsReferenceImage(request.Subject)
                              ? "Attach `assets/mascot/mascot-idle.png` as the reference image."
                              : "No reference image needed."));
            if (request.Subject.Kind == ArtKind.ExercisePair)
            {
                sb.AppendLine("Both poses in ONE wide image - it is split into the two poses automatically.");
            }

            sb.AppendLine();
            sb.AppendLine("```");
            sb.AppendLine(request.Prompt);
            sb.AppendLine("```");
        }

        return sb.ToString();
    }
}
